class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function sumOddLengthSubarrays($arr) {
        $n = count($arr);
        $sum = 0;
        for ($i = 0; $i < $n; $i++) {
            // Number of subarrays containing index i:
            // (i + 1) choices for start, (n - i) choices for end.
            $total = ($i + 1) * ($n - $i);
            // Exactly ceil(total / 2) of them have odd length.
            $oddCount = intdiv($total + 1, 2);
            $sum += $arr[$i] * $oddCount;
        }
        return $sum;
    }
}

